import { STUDY_STAGES, benchmarkKey } from './study.js';
import { PROCESS_LIBRARY, PROCESS_SOURCES } from './process-library.js';
import { analyseProcess } from './process-analysis.js';
import { CASE_TABS, STAGES, SKILLS, SOURCE_STATES, DEPLOY_CHECKS, INPUT_GROUPS } from './data.js';
import { MODEL_VERSION, evaluateCase, evaluateScenario, recommendCase, stressScenario, fitAction, readiness, observationMetrics } from './engine.js';

export const htmlEscape = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
export const euro = value => value == null || !Number.isFinite(value) ? 'Not known' : new Intl.NumberFormat('en-GB', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0 }).format(value);
export const unitEuro = value => value == null || !Number.isFinite(value) ? 'Not known' : new Intl.NumberFormat('en-GB', { style: 'currency', currency: 'EUR', minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(value);
export const number = (value, digits = 1) => value == null || !Number.isFinite(value) ? '—' : new Intl.NumberFormat('en-GB', { maximumFractionDigits: digits }).format(value);
const h = htmlEscape;
const paths = {
  grid: '<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  layers: '<path d="m12 3 10 6-10 6L2 9l10-6Zm-9 12 9 6 9-6M3 12l9 6 9-6"/>',
  robot: '<rect x="5" y="6" width="14" height="13" rx="3"/><path d="M12 3v3M2 11v4m20-4v4M8 19v3m8-3v3M8 11h1m6 0h1m-7 4h6"/>',
  book: '<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1v15"/>',
  file: '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-6-6v6h6M8 12h8m-8 4h5"/>',
  plus: '<path d="M12 5v14M5 12h14"/>',
  arrow: '<path d="M5 12h14m-6-6 6 6-6 6"/>',
  down: '<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
  check: '<path d="m5 12 4 4L19 6"/>',
  search: '<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',
  activity: '<path d="M2 12h4l3-8 6 16 3-8h4"/>',
  clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
  globe: '<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z"/>',
  brief: '<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12h18m-9-2v4"/>',
  menu: '<path d="M4 6h16M4 12h16M4 18h16"/>',
  close: '<path d="m6 6 12 12M6 18 18 6"/>',
  person: '<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',
  link: '<path d="m10 13 4-4m-7 7-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m2 2 1-1a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>'
};
export const icon = name => `<svg class="icon" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.file}</svg>`;
export const chip = (text, type = '') => `<span class="chip ${type}">${h(text)}</span>`;
export const button = (text, action, { id = '', kind = 'secondary', extra = '', iconName = '' } = {}) => `<button class="button ${kind}" data-action="${h(action)}" ${id ? `data-id="${h(id)}"` : ''} ${extra}>${iconName ? icon(iconName) : ''}${h(text)}</button>`;
export const empty = (title, detail, action = '') => `<div class="empty"><div class="empty-icon">${icon('layers')}</div><h3>${h(title)}</h3><p>${h(detail)}</p>${action}</div>`;
const titleRow = (title, detail = '', action = '') => `<div class="section-title"><div><h2>${h(title)}</h2>${detail ? `<p>${h(detail)}</p>` : ''}</div>${action}</div>`;
export const panel = (title, detail, body, action = '', className = '') => `<section class="panel ${className}">${titleRow(title, detail, action)}${body}</section>`;
export const metric = (label, value, detail = '', tone = '', glyph = 'activity') => `<div class="metric ${tone}"><div class="metric-label">${h(label)}${icon(glyph)}</div><div class="metric-value">${h(value)}</div><div class="metric-detail">${h(detail)}</div></div>`;
const safeOptions = (values, current) => values.map(value => { const [id,label] = Array.isArray(value) ? value : [value,value]; return `<option value="${h(id)}" ${String(id) === String(current) ? 'selected' : ''}>${h(label)}</option>`; }).join('');
export function inputField(path, label, value, { unit = '', help = '', type = 'number', step = 'any', min = 0, max = '', prefix = 'field', required = false } = {}) {
  const id = `${prefix}-${path.replace(/[^a-zA-Z0-9]/g, '-')}`;
  return `<div class="field"><label for="${id}">${h(label)}${unit ? `<span>${h(unit)}</span>` : ''}</label><input id="${id}" ${prefix === 'field' ? `data-field="${h(path)}"` : `name="${h(path)}"`} type="${type}" value="${h(value)}" ${type === 'number' ? `step="${step}" min="${min}" ${max !== '' ? `max="${max}"` : ''}` : ''} ${required ? 'required' : ''} placeholder="${type === 'number' ? 'Not known' : ''}" ${help ? `aria-describedby="${id}-help"` : ''}>${help ? `<small id="${id}-help">${h(help)}</small>` : ''}</div>`;
}
export function selectField(path, label, value, options, { help = '', prefix = 'field' } = {}) {
  const id = `${prefix}-${path.replace(/[^a-zA-Z0-9]/g, '-')}`;
  return `<div class="field"><label for="${id}">${h(label)}</label><select id="${id}" ${prefix === 'field' ? `data-field="${h(path)}"` : `name="${h(path)}"`}>${safeOptions(options, value)}</select>${help ? `<small>${h(help)}</small>` : ''}</div>`;
}
const noteField = (path, label, value, help = '') => `<div class="field wide"><label for="note-${h(path)}">${h(label)}</label><textarea id="note-${h(path)}" data-field="${h(path)}" rows="3">${h(value)}</textarea>${help ? `<small>${h(help)}</small>` : ''}</div>`;
export const gridFields = items => `<div class="fields">${items.join('')}</div>`;
export const table = (headers, rows, className = '') => `<div class="table-scroll"><table class="${className}"><thead><tr>${headers.map(x => `<th>${h(x)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
export const row = cells => `<tr>${cells.map(x => `<td>${x}</td>`).join('')}</tr>`;
const progress = (value, tone = '') => `<span class="bar ${tone}"><i style="width:${Math.max(0, Math.min(100, value || 0))}%"></i></span>`;
const resultStatus = r => chip(({ candidate: 'Candidate for study', 'not-feasible': 'Constraint not met', 'needs-data': 'Needs data', 'no-business-case': 'No business case', baseline: 'Current method', 'no-demand': 'No demand' })[r.status] || r.status, r.status === 'candidate' ? 'green' : r.status === 'baseline' ? '' : 'amber');
const viewLink = (c, tab = '', label = 'Open case') => button(label, 'open-case', { id: c.id, kind: 'text', extra: tab ? `data-tab="${tab}"` : '', iconName: 'arrow' });
const selected = ctx => ctx.c.scenarios.find(s => s.id === ctx.c.selectedScenarioId) || ctx.c.scenarios[0];
const selectedResult = ctx => evaluateScenario(ctx.c, selected(ctx), ctx.w.configs);
const scenarioPicker = ctx => `<label class="inline-label">Option<select data-action="select-scenario" aria-label="Selected option">${safeOptions(ctx.c.scenarios.map(s => [s.id, s.name]), ctx.c.selectedScenarioId)}</select></label>`;

function appSidebar(ctx) {
  const item=(label,glyph,view,tab='')=>{
    const active=tab?ctx.view==='case'&&(tab==='Overview'?!['Deployment','Learning'].includes(ctx.tab):ctx.tab===tab):ctx.view===view;
    return `<button data-action="${tab?'open-case':'navigate'}" data-id="${h(tab?ctx.c.id:view)}" ${tab?`data-tab="${tab}"`:''} class="nav-item ${active?'active':''}" ${active?'aria-current="page"':''}>${icon(glyph)}<span>${h(label)}</span>${view==='pipeline'?`<b>${ctx.w.cases.length}</b>`:''}</button>`;
  };
  const groups=[
    ['Dashboards',item('Executive cockpit','grid','executive')+item('Evaluation pipeline','layers','pipeline')+item('Deployment overview','robot','deployments')],
    ['Evaluation',item('Select a process','plus','evaluations')+item('Current evaluation','layers','case','Overview')],
    ['Deployment',item('Delivery plan','robot','case','Deployment')+item('Pilot and learning','activity','case','Learning')],
    ['AWS programme',item('AWS deployment plan','layers','aws-plan')],
    ['Libraries',item('Processes','book','processes')+item('Technology','book','catalog')]
  ];
  return `<aside class="sidebar ${ctx.mobileMenu?'is-open':''}" aria-label="Main navigation" ${ctx.isMobile&&!ctx.mobileMenu?'inert':''}><a class="brand" href="#evaluations"><span class="brand-mark">h<span>+</span></span><span>Hybrid<br><strong>Workforce</strong></span></a><nav aria-label="Workspace sections">${groups.map(([title,items])=>`<section class="nav-group" aria-label="${title}"><h2 class="nav-group-title">${title}</h2>${items}</section>`).join('')}</nav><div class="sidebar-case"><span class="nav-label">ACTIVE CASE</span><strong>${h(ctx.c.name)}</strong><span>${h(ctx.c.site)}</span><button class="sidebar-evidence ${ctx.view==='evidence'?'active':''}" data-action="navigate" data-id="evidence" ${ctx.view==='evidence'?'aria-current="page"':''}>${icon('file')}<span>Evidence and questions</span></button><small>Sources, gaps, and decisions for this case.</small></div><div class="sidebar-footer"><div class="sidebar-runtime"><span class="online-dot"></span> Local prototype <span class="version">v2</span></div><a href="docs/v2-design/design-review.html" target="_blank" rel="noopener">Design basis ${icon('link')}</a></div></aside>`;
}

export function renderApp(ctx) {
  const title = { executive:'Executive cockpit', pipeline:'Evaluation pipeline', evaluations:'Evaluation centre', processes:'Process library', deployments:'Deployments', catalog:'Technology library', evidence:'Evidence & questions', workflow:'How it works', case:'Evaluation workspace', 'aws-plan':'AWS deployment plan' }[ctx.view] || 'Executive';
  return `${appSidebar(ctx)}${ctx.mobileMenu?'<button class="nav-scrim" data-action="toggle-menu" aria-label="Close navigation"></button>':''}<div class="app-main"><header class="topbar"><div class="topbar-left"><button class="icon-button mobile-toggle" data-action="toggle-menu" aria-label="Toggle navigation">${icon('menu')}</button><span class="crumb">Hybrid Workforce <span>/</span> <strong>${title}</strong></span></div><div class="topbar-right"><span class="save-status" id="save-status">${h(ctx.saveStatus)}</span><label class="sr-only" for="role-view">View role</label><select id="role-view" data-action="role-view" class="role-select">${safeOptions(['Engineer view','Executive view','Site view','Delivery view'],ctx.role)}</select>${button('How it works','navigate',{id:'workflow',kind:'quiet help-link',iconName:'book',extra:'aria-label="Help: How it works"'})}${button('Export', 'export-workspace', { iconName: 'down', kind:'quiet' })}</div></header><main id="main-content"><div class="prototype-line"><span class="dot amber-dot"></span><strong>Planning prototype</strong><span>Example cases use sample data. External robotics services are not connected.</span></div>${ctx.view === 'case' ? caseView(ctx) : globalView(ctx)}</main><footer class="app-footer"><span>Hybrid Workforce · ${h(ctx.c.site)}</span><span>Local records · Planning model 2.1 · No live robot control</span></footer></div><div id="toast" class="toast" role="status" aria-live="polite"></div><dialog id="app-dialog" aria-labelledby="dialog-title"></dialog>`;
}

function globalView(ctx) {
  if (ctx.view === 'aws-plan') return simulationView(ctx);
  if (ctx.view === 'pipeline') return evaluationsView(ctx,true);
  if (ctx.view === 'processes') return processLibraryView(ctx);
  if (ctx.view === 'workflow') return workflowView(ctx);
  if (ctx.view === 'evaluations') return evaluationsView(ctx);
  if (ctx.view === 'deployments') return deploymentsView(ctx);
  if (ctx.view === 'catalog') return catalogView(ctx);
  if (ctx.view === 'evidence') return evidenceView(ctx);
  return executiveView(ctx);
}

function executiveView(ctx) {
  const records = ctx.w.cases.map(c => ({ c, rec: recommendCase(c, ctx.w.configs) }));
  const filtered = ctx.siteFilter ? records.filter(x => x.c.site === ctx.siteFilter) : records;
  const forecast = filtered.reduce((sum,x) => sum + Math.max(0,x.rec.best?.annualNet || 0),0);
  const approved = filtered.filter(x => x.c.decision?.revision === x.c.revision && x.c.decision?.outcome === 'Proceed to evidence study' && x.c.decision.result?.modelVersion === MODEL_VERSION);
  const assets = filtered.flatMap(x => x.c.deployment.assets);
  const observed = filtered.flatMap(x => x.c.observations).filter(o => o.status === 'Measured');
  const approvedCash = approved.reduce((sum,x)=>sum+(x.c.decision.result?.annualNet||0),0);
  const comparable = observed.filter(o=>o.baselineCost!=null&&!observationMetrics(o).errors.length);
  const observedDelta = comparable.length ? comparable.reduce((sum,o)=>sum+observationMetrics(o).costDelta,0) : null;
  return `<div class="page-heading"><div><h1>Executive cockpit</h1><p>Portfolio forecasts, evaluation status, and measured site results.</p></div>${button('New evaluation','new-case',{kind:'primary',iconName:'plus'})}</div><div class="toolbar"><div class="segmented"><button class="selected" data-action="navigate" data-id="executive">Portfolio view</button><button data-action="navigate" data-id="deployments">Site delivery</button></div><label class="inline-label">Site<select data-action="site-filter" aria-label="Filter site"><option value="">All sites</option>${safeOptions([...new Set(ctx.w.cases.map(c=>c.site))],ctx.siteFilter)}</select></label></div><div class="metrics">${metric('Forecast annual cash saving',euro(forecast),'Best tested candidate per case · sample inputs','green','brief')}${metric('Initiatives in review',number(filtered.length,0),`${filtered.filter(x=>x.rec.best).length} with a modelled candidate`,'','layers')}${metric('Study decisions',number(approved.length,0),'Current recorded decisions · not pilot approval','','check')}${metric('Measured field results',number(observed.length,0),'Sample observations are excluded','','activity')}</div><div class="two-columns portfolio-grid">${panel('Case stages','Case count by stage.',`<div class="journey-strip">${[['Define','Describe the work'],['Evaluate','Compare options'],['Decide','Review the case'],['Prepare','Prepare delivery'],['Pilot','Measure a trial'],['Operate','Improve the result']].map(([stage,label],i)=>`<div><span class="journey-index">${String(i+1).padStart(2,'0')}</span><strong>${stage}</strong><small>${label}</small><b>${filtered.filter(x=>x.c.stage===stage).length}</b></div>`).join('')}</div><div class="callout subtle">${icon('file')}<div><strong>Forecast is separate from observed value.</strong><p>A positive planning result is a reason to collect evidence. It is not a proven site saving.</p></div></div>`,button('View pipeline','navigate',{id:'evaluations',kind:'text',iconName:'arrow'}))}${panel('Delivery snapshot','Planned, in pilot, and in service.',`<div class="delivery-number">${assets.length}<span>asset records</span></div><div class="mini-stats"><div><b>${assets.filter(a=>a.status==='In pilot').length}</b><span>In pilot</span></div><div><b>${assets.filter(a=>a.status==='In service').length}</b><span>In service</span></div><div><b>${assets.filter(a=>a.status==='Planned').length}</b><span>Planned</span></div></div><p class="muted">These records are local. The sample pilot does not represent a live installation.</p>`,button('Open deployments','navigate',{id:'deployments',kind:'text'}))}</div>${panel('Value basis','Forecast, approved study scope, and measured windows have different meanings.',table(['Measure','Value','Basis'],[row(['Forecast annual cash saving',euro(forecast),'Best tested candidate per case. Conditional on the entered assumptions.']),row(['Approved study forecast',euro(approvedCash),'Current decisions to study the selected option. This does not authorize a pilot or establish savings.']),row(['Measured window cost delta',euro(observedDelta),'Only measured records with an entered comparable baseline cost. This is not annualised.'])]))}${panel('Evaluation portfolio','Forecast values use the best feasible option in the tested set.',table(['Initiative / site','Stage','Best tested option','Annual net cash','Payback','Evidence',''],filtered.map(({c,rec})=>row([`<strong>${h(c.name)}</strong><small>${h(c.site)}</small>`,chip(c.stage),rec.best?h(rec.best.name):'No supported candidate',euro(rec.best?.annualNet),rec.best?.payback!=null?`${number(rec.best.payback)} years`:'—',chip(rec.best?.evidence||'Inputs needed','amber'),viewLink(c)]))))}`;
}

function evaluationsView(ctx, dashboardOnly=false) {
  const cases = ctx.w.cases.filter(c => (!ctx.search || `${c.name} ${c.site} ${c.owner}`.toLowerCase().includes(ctx.search.toLowerCase())) && (!ctx.stageFilter || c.stage === ctx.stageFilter));
  return `<div class="page-heading"><div><h1>${dashboardOnly?'Evaluation pipeline':'Process evaluation'}</h1><p>${dashboardOnly?'Track cases, evidence gaps, and forecast results. Open a case to do the work.':'Select a process or open an existing evaluation.'}</p></div>${button('New evaluation','new-case',{kind:'primary',iconName:'plus'})}</div>${dashboardOnly?'':processLibraryView(ctx,true)}<div class="toolbar"><div class="search-box">${icon('search')}<input type="search" data-action="case-search" aria-label="Search evaluations" value="${h(ctx.search)}" placeholder="Find a process, site, or owner"></div><label class="inline-label">Stage<select data-action="stage-filter" aria-label="Filter stage"><option value="">All stages</option>${safeOptions(STAGES,ctx.stageFilter)}</select></label><div class="toolbar-actions">${button('Import workspace','import-workspace',{iconName:'file'})}<input type="file" id="workspace-import" accept=".json" hidden></div></div><div class="case-cards">${cases.map(c=>{const rec=recommendCase(c,ctx.w.configs), gaps=c.sources.filter(s=>['Unknown','Out of date'].includes(s.status)).length;return `<article class="case-card"><div class="card-top">${chip(c.stage,c.stage==='Pilot'?'purple':'')}${chip(c.processTemplateId?'Engineering draft':c.sample?'Sample case':'User case')}</div><div class="case-symbol">${icon(c.id==='case-amr'?'robot':'layers')}</div><h2>${h(c.name)}</h2><p>${h(c.site)} · ${h(c.country)}</p><div class="case-stats"><div><span>Daily demand</span><b>${number(c.baseline.demandDaily,0)}</b></div><div><span>Forecast annual net</span><b>${euro(rec.best?.annualNet)}</b></div></div><div class="case-next"><span class="dot amber-dot"></span>${gaps?`${gaps} source gaps to resolve`:'Review the current evidence'}</div><div class="card-footer"><span class="avatar">${h(c.owner.slice(0,1))}</span><span>${h(c.owner)}</span>${viewLink(c)}</div></article>`;}).join('')||empty('No evaluations match','Change the search or add a case.')}</div>`;
}

function deploymentsView(ctx) {
  const assets=ctx.w.cases.flatMap(c=>c.deployment.assets.map(a=>({...a,c}))), pilot=assets.filter(a=>a.status==='In pilot').length;
  return `<div class="page-heading"><div><h1>Deployment overview</h1><p>Site assets, delivery plans, and release status.</p></div>${button('Plan an asset','add-asset',{kind:'primary',iconName:'plus'})}</div><div class="metrics">${metric('Asset records',number(assets.length,0),'Local register','','robot')}${metric('In pilot',number(pilot,0),'Supervised trial stage','purple','activity')}${metric('In service',number(assets.filter(a=>a.status==='In service').length,0),'Recorded status · no live feed','','check')}${metric('Sites with delivery plans',number(ctx.w.cases.filter(c=>c.deployment.siteNotes||c.deployment.assets.length).length,0),'Draft plans and sample sites','','globe')}</div>${panel('Site and asset register','The status is entered by a user. Live telemetry is not connected.',assets.length?table(['Asset / source','Site / process','Configuration','Release','Status',''],assets.map(a=>row([`<strong>${h(a.name)}</strong><small>${h(a.serial)}</small>`,`<strong>${h(a.c.site)}</strong><small>${h(a.c.name)}</small>`,h(ctx.w.configs.find(v=>v.id===a.configId)?.name||a.configId),h(a.release),chip(a.status,a.status==='In pilot'?'purple':''),button('Edit asset','edit-asset',{id:a.id,extra:`data-case="${h(a.c.id)}"`})]))):empty('No asset records','Prepare a plan in a case, then add the intended hardware.'))}${panel('Delivery plans','Open the selected case to complete its plan.',`<div class="delivery-cards">${ctx.w.cases.map(c=>{const ready=readiness(c,ctx.w.configs);return `<div><div class="card-top"><strong>${h(c.name)}</strong>${chip(`${8-DEPLOY_CHECKS.filter(([key])=>!c.deployment.checklist[key]).length}/8 review items`)}</div><p>${h(c.site)}</p>${progress((8-DEPLOY_CHECKS.filter(([key])=>!c.deployment.checklist[key]).length)/8*100)}<small>${ready.gaps.length} open readiness items</small>${viewLink(c,'Deployment','Open plan')}</div>`;}).join('')}</div>`)}`;
}

function catalogView(ctx) {
  const real=ctx.w.configs.filter(v=>v.realProduct),samples=ctx.w.configs.filter(v=>!v.realProduct);
  const cards=values=>`<div class="technology-cards">${values.map(v=>`<article class="technology-card"><div class="card-top">${chip(v.family,'purple')}${chip(v.source,v.source==='Unknown'?'amber':'')}</div><h2>${h(v.name)}</h2><p>${h(v.description)}</p>${v.excludedFromMatching?`<div class="callout subtle">Reference variant. Excluded from automatic matching.</div>`:''}<div class="spec-grid"><div><span>Published payload</span><b>${v.payloadKg==null?'Not established':number(v.payloadKg)+' kg'}</b></div><div><span>Published reach</span><b>${v.reachM==null?'Not established':number(v.reachM,3)+' m'}</b></div><div><span>Hardware CAPEX · EUR/unit</span><b>${euro(v.price)}</b></div><div><span>Service + energy · EUR/unit/year</span><b>${v.supportAnnual==null||v.energyAnnual==null?'Not known':euro(v.supportAnnual+v.energyAnnual)}</b></div><div><span>Other CAPEX · EUR/unit</span><b>${v.realProduct?euro(v.extraCapex):'See case inputs'}</b></div><div><span>Other OPEX · EUR/unit/year</span><b>${v.realProduct?euro(v.extraOpexAnnual):'See case inputs'}</b></div></div>${v.publishedPrice?`<p class="published-price"><strong>${h(v.publishedPrice.currency)} ${number(v.publishedPrice.amount,0)}</strong> · published listing</p><small>${h(v.publishedPrice.basis)}</small><p class="muted">Not converted to EUR. Not used automatically in the business case.</p>`:v.realProduct?'<p class="muted">Complete public price not found. Request a scoped quote.</p>':''}${v.publishedSpecs?`<details><summary>Published specification detail</summary><dl class="product-specs">${Object.entries(v.publishedSpecs).map(([key,value])=>`<dt>${h(key)}</dt><dd>${h(value)}</dd>`).join('')}</dl></details>`:''}<p class="muted">${h(v.costNote||'Sample cost assumptions.')}</p>${v.sourceUrl?`<a href="${h(safeHttpUrl(v.sourceUrl))}" target="_blank" rel="noopener">Manufacturer source ↗</a>`:''}${(v.extraSources||[]).map(x=>`<p><a href="${h(safeHttpUrl(x.url))}" target="_blank" rel="noopener">${h(x.label)} ↗</a></p>`).join('')}<p>${chip(v.commercialStatus||'Sample','amber')} <small>EUR cost basis: ${h(v.commercialSource||'Not recorded')}</small></p><div class="skill-tags">${v.skills.map(x=>`<span>${h(x)}</span>`).join('')}</div><div class="card-footer"><small>Checked ${h(v.sourceDate)} · record v${v.revision}</small>${button('View / edit','edit-config',{id:v.id,kind:'text',iconName:'arrow'})}</div></article>`).join('')}</div>`;
  return `<div class="page-heading"><div><h1>Technology library</h1><p>Product specifications, task evidence, and capital and operating costs.</p></div>${button('Add configuration','new-config',{kind:'primary',iconName:'plus'})}</div><div class="callout"><div><strong>Manufacturer specifications are not warehouse task results.</strong><p>Public specifications and list prices have sources. Unpublished costs stay unknown. Enter reviewed EUR costs before a business case. Tools, software, charging, installation, maintenance, and support need an explicit scope.</p><p><a href="docs/product-quote-template.csv" download>Download the cost quote checklist</a></p></div></div>${cards(real)}<details class="sample-catalog"><summary>Earlier sample configurations · ${samples.length} records</summary><p>These records remain for existing demonstration cases. They are fictional and are excluded from the new process-library analysis.</p>${cards(samples)}</details>`;
}
function safeHttpUrl(value) { try {const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'#';}catch{return '#';} }

function evidenceView(ctx) {
  const sourceRows=ctx.w.cases.filter(c=>c.id===ctx.c.id).flatMap(c=>c.sources.map(s=>row([`<strong>${h(s.name)}</strong><small>${h(s.type)}</small>`,h(c.name),chip(s.status,['Unknown','Out of date'].includes(s.status)?'amber':''),h(s.note),viewLink(c,'Inputs','Review source')])));
  const qs=ctx.questions.filter(q=>(!ctx.questionGroup||q.group===ctx.questionGroup)&&(!ctx.questionSearch||`${q.question} ${q.proposed_default}`.toLowerCase().includes(ctx.questionSearch.toLowerCase())));
  return `<div class="page-heading"><div><h1>Evidence and questions</h1><p>Sources, gaps, and decisions for ${h(ctx.c.name)}. Evidence supports both evaluation and delivery.</p></div><label class="inline-label">Active case<select data-action="select-case" aria-label="Evidence case">${safeOptions(ctx.w.cases.map(c=>[c.id,c.name]),ctx.c.id)}</select></label></div>${panel('Source register','Sources are linked to their case and can be reviewed there.',table(['Source','Case','Status','Notes',''],sourceRows))}${panel('Questions from the design review','Record answers for the current case. Proposed defaults remain visible.',`<div class="toolbar"><label class="inline-label">Area<select data-action="question-group" aria-label="Question area"><option value="">All areas</option>${safeOptions([...new Set(ctx.questions.map(q=>q.group))],ctx.questionGroup)}</select></label><div class="search-box">${icon('search')}<input type="search" aria-label="Search questions" data-action="question-search" value="${h(ctx.questionSearch)}" placeholder="Search the open questions"></div><small>Answers apply to ${h(ctx.c.name)}</small></div><div class="question-list">${qs.map(q=>`<details><summary><span class="question-id">${q.id}</span><span>${h(q.question)}</span>${chip(ctx.c.answers[q.id]?'Answer recorded':q.decision_time,ctx.c.answers[q.id]?'green':'')}</summary><div class="question-body"><div><small>PROPOSED DEFAULT</small><p>${h(q.proposed_default)}</p><small>PROPOSED OWNER</small><p>${h(q.proposed_owner)}</p></div><div class="field"><label for="answer-${q.id}">Case answer</label><textarea id="answer-${q.id}" data-question="${q.id}" rows="3" placeholder="Record the answer, source, and remaining limits.">${h(ctx.c.answers[q.id]||'')}</textarea></div></div></details>`).join('')}</div>`)}`;
}

function caseView(ctx) {
  const c=ctx.c;
  return `<div class="case-heading"><div><div class="eyebrow">EVALUATION / ${h(c.site)}</div><h1>${h(c.name)}</h1><p>${h(c.purpose)}</p></div><div class="case-heading-actions"><select aria-label="Current case" data-action="select-case">${safeOptions(ctx.w.cases.map(x=>[x.id,x.name]),c.id)}</select>${button('Edit case','edit-case',{kind:'quiet'})}</div></div><div class="case-meta">${chip(c.stage,'green')}${chip(c.processTemplateId?'Engineering draft':c.sample?'Sample inputs':'User inputs')}${chip(`Version ${c.revision}`)}<span>${icon('person')}${h(c.owner)}</span><span>${icon('globe')}${h(c.country)}</span><span class="meta-right">${button('Export case','export-case',{kind:'text',iconName:'down'})}${button('Report','report',{kind:'text',iconName:'file'})}</span></div><div class="evaluation-path"><strong>Define the work → match the capabilities → compare the team → build the business case</strong><span>Missing data or failed constraints return to the earlier step. Deployment follows a separate readiness review.</span></div><nav class="case-tabs" aria-label="Case stages">${CASE_TABS.map((tab,i)=>`<button data-action="case-tab" data-id="${tab}" class="${ctx.tab===tab?'active':''}"><span>${String(i+1).padStart(2,'0')}</span>${tab==='Results'?'Business case':tab}</button>`).join('')}</nav><div class="case-content">${({Overview:caseOverview,Inputs:inputsView,Process:processView,Matches:matchesView,Scenarios:scenariosView,Results:resultsView,Deployment:deploymentView,Learning:learningView}[ctx.tab]||caseOverview)(ctx)}</div>`;
}

function caseOverview(ctx) {
  const {c}=ctx, rec=recommendCase(c,ctx.w.configs), result=selectedResult(ctx), sourceGaps=c.sources.filter(s=>s.status==='Unknown').length;
  return `<div class="overview-hero"><div><span class="eyebrow">THE NEXT USEFUL DECISION</span><h2>${rec.best?'Test a complete hybrid process.':'Complete the process evidence.'}</h2><p>${h(rec.text)}</p>${button('Review the process','case-tab',{id:'Process',kind:'primary',iconName:'arrow'})}</div><div class="overview-illustration" aria-hidden="true"><span class="illustration-human">${icon('person')}</span><i>+</i><span class="illustration-robot">${icon('robot')}</span><div class="illustration-line"></div><span class="illustration-label">One process. Shared work.</span></div></div><div class="metrics">${metric('Daily demand',number(c.baseline.demandDaily,0),'Across all shifts · sample baseline','','layers')}${metric('Actions in the process',String(c.actions.length),'Each action has timing and capability needs','','file')}${metric('Forecast annual cash',euro(rec.best?.annualNet),'Best tested feasible option','green','brief')}${metric('Source gaps',String(sourceGaps),'Unknown sources need a clear next action','amber','file')}</div><div class="two-columns">${panel('Case brief','Keep the demand side and supply side connected.',`<dl class="definition-list"><div><dt>Demand</dt><dd>${h(c.name)} · ${number(c.baseline.demandDaily,0)} units/day</dd></div><div><dt>Human baseline</dt><dd>${number(c.baseline.peoplePerShift)} people/shift · ${c.baseline.shifts} shifts</dd></div><div><dt>Selected option</dt><dd>${h(result.name)}</dd></div><div><dt>Financial view</dt><dd>${h(c.economics.benefitMode)} · ${c.economics.retainedPct}% retained labour benefit</dd></div><div><dt>Technology route</dt><dd>${h(c.deployment.route)}</dd></div></dl>`)}${panel('Next actions','Work through the case or open any draft stage.',`<div class="next-list">${[['Inputs','Check the baseline','Reconcile demand, people, and task time.'],['Matches','Check action-level fit','Review blocked and unknown configurations.'],['Results','Review the business case','Separate time removed, staffing, and cash.'],['Deployment','Prepare the delivery path','Name the hardware, stack, tests, and owner.']].map(([tab,title,desc])=>`<button data-action="case-tab" data-id="${tab}"><span class="next-icon">${icon(tab==='Deployment'?'robot':'arrow')}</span><span><strong>${title}</strong><small>${desc}</small></span>${icon('arrow')}</button>`).join('')}</div>`)}</div>`;
}

function inputsView(ctx) {
  const {c}=ctx,b=c.baseline,e=c.economics;
  const baseResult=evaluateScenario(c,c.scenarios.find(x=>x.kind==='manual')||c.scenarios[0],ctx.w.configs);
  const baselineCheck=panel('Baseline reconciliation','Check the staffing and timing model before interpreting the opportunity.',table(['Measure','Entered or calculated value','Basis'],[row(['Human work per unit',`${number(baseResult.baselineSeconds)} s`,'Sum of action time × frequency. Parallel work is excluded from this screening calculation.']),row(['Average / peak demand',`${number(baseResult.avgHour)} / ${number(baseResult.peakHour)} units/h`,'Daily demand across all operating shifts. Peak factor is used for capacity, not annual demand.']),row(['Human capacity',`${number(baseResult.capacity)} units/h`,baseResult.meetsDemand?'The entered staffing meets the peak screening requirement.':'The entered staffing or time model does not establish enough peak capacity. Reconcile it with site evidence.']),row(['Annual staffing positions',number(baseResult.baselineFte),'People per shift × shifts × annual cover factor. Confirm the engineering model and observed allocation.']),row(['Observed output',b.observedUph==null?'Not recorded':`${number(b.observedUph)} units/h`,'A site observation is separate from the engineering and action-time estimates.'])]));
  return `${inputRegister(ctx)}${panel('Source files and evidence','Add a file or record a source. CAD, video, and model files remain references until an adapter is connected.',table(['Source / type','Status','Date','Basis / missing data',''],c.sources.map(s=>row([`<strong>${h(s.name)}</strong><small>${h(s.type)}</small>`,chip(s.status,['Unknown','Out of date'].includes(s.status)?'amber':''),h(s.date||'Not known'),`<span>${h(s.note)}</span>${s.fileId?`<a class="file-link" href="/api/files/${encodeURIComponent(s.fileId)}" target="_blank" rel="noopener">Open stored file</a>`:''}`,button('Edit','edit-source',{id:s.id})]))),`<div class="action-group">${button('Add source','new-source',{iconName:'plus'})}${button('Attach file','attach-file',{iconName:'file'})}<input type="file" id="source-file" hidden></div>`)}<div class="two-columns">${panel('Demand and operating calendar','Use the same demand and calendar for every option.',gridFields([
    inputField('baseline.demandDaily','Daily demand',b.demandDaily,{unit:'units/day'}),inputField('baseline.peakFactor','Peak factor',b.peakFactor,{unit:'× average hour',min:1}),inputField('baseline.shifts','Shifts per day',b.shifts,{step:1,min:1}),inputField('baseline.shiftHours','Hours per shift',b.shiftHours,{unit:'h'}),inputField('baseline.daysYear','Operating days',b.daysYear,{unit:'days/year',step:1,min:1,max:366}),inputField('baseline.qualityTargetPct','First-pass quality target',b.qualityTargetPct,{unit:'%',max:100,help:'Planning assumption. Check actual task and process quality evidence.'})
  ]))}${panel('Human baseline','Positions are counted per shift. Annual FTE positions include every shift.',gridFields([
    inputField('baseline.peoplePerShift','Current people per shift',b.peoplePerShift,{unit:'people',step:1}),inputField('baseline.minPeoplePerShift','Minimum retained coverage',b.minPeoplePerShift,{unit:'people/shift',step:1}),inputField('baseline.salaryAnnual','Fully loaded annual cost',b.salaryAnnual,{unit:'EUR/person/year'}),inputField('baseline.humanUtilPct','Productive share of shift',b.humanUtilPct,{unit:'%',min:1,max:100}),inputField('baseline.staffingCover','Staffing cover factor',b.staffingCover,{unit:'×',min:1,help:'Cover for the annual staffing plan. Do not add absence twice.'}),inputField('baseline.observedUph','Observed average output',b.observedUph,{unit:'units/h',help:'Optional. Record the observation period and source in the input register.'}),inputField('baseline.routeM','Reference route length',b.routeM,{unit:'m',help:'Context only. The current model uses recorded task times, not a generated travel path.'})
  ]))}</div>${panel('Engineering and layout context','This annotated plan is a sample. Enter dimensions and attach the real site plan.',`<div class="layout-preview"><div class="layout-grid"><div class="layout-zone infeed">Infeed<small>Presented totes</small></div><div class="layout-zone human-zone">Human work<small>Inspect · scan · exchange</small></div><div class="layout-route">${icon('arrow')}<span>${number(b.routeM)} m · assumed</span>${icon('arrow')}</div><div class="layout-zone robot-zone">Robot work<small>Lift · move · place</small></div><div class="layout-zone destination">Sort points<small>Destination carriers</small></div><div class="layout-charge">${icon('robot')} Charge / recovery area</div></div><div class="layout-note">Sample 2D context<br>No CAD interpretation<br>No collision or safety check</div></div>`)}${panel('Commercial and business-case inputs','All amounts are EUR scenario inputs. Price and service inclusions are stored in the technology library.',gridFields([
    selectField('economics.commercialModel','Commercial model',e.commercialModel,[['purchase','Purchase'],['lease','Lease'],['raas','RaaS']]),selectField('economics.benefitMode','Benefit basis',e.benefitMode,['Avoided hires','Cash labour reduction','Redeployed capacity'],{help:'Redeployed capacity is shown as capacity value, not cash labour savings.'}),inputField('economics.cashableFte','Positions that can create cash benefit',e.cashableFte,{unit:'annual FTE',help:'Explicit assumption. The model caps this at the achievable staffing change.'}),inputField('economics.retainedPct','Labour benefit retained',e.retainedPct,{unit:'%',max:100}),inputField('economics.integration','Integration and commissioning',e.integration,{unit:'EUR once'}),inputField('economics.siteChanges','Tools and site changes',e.siteChanges,{unit:'EUR once'}),inputField('economics.softwareAnnual','Platform / software cost',e.softwareAnnual,{unit:'EUR/year'}),inputField('economics.supportAnnual','Additional site support',e.supportAnnual,{unit:'EUR/year',help:'Exclude support already included in the robot price or contract.'}),inputField('economics.rampMonths','Months before full benefit',e.rampMonths,{unit:'months',max:12}),inputField('economics.horizonYears','Study / contract horizon',e.horizonYears,{unit:'years',min:1,max:20,step:1}),inputField('economics.discountPct','Discount rate',e.discountPct,{unit:'%',max:100,help:'Scenario assumption, not an approved finance rate.'}),inputField('economics.residualValue','Residual value at study end',e.residualValue,{unit:'EUR'}),inputField('economics.otherBenefitAnnual','Other captured cash benefit',e.otherBenefitAnnual,{unit:'EUR/year',help:'Only enter a supported benefit that is not already counted.'}),inputField('economics.handoffSec','Human work per handoff',e.handoffSec,{unit:'s/transition'})
  ]))}${baselineCheck}${panel('Data completeness','An empty number stays unknown. Correct invalid entries before you use a result.',`<div class="callout subtle"><div><strong>Source status does not follow financial performance.</strong><p>A positive business case cannot turn sample task times into measured performance. The engineering-model and MTM reconciliation remains a visible source review.</p></div></div>`)}`;
}

function processView(ctx) {
  const c=ctx.c,s=selected(ctx),r=selectedResult(ctx);
  return `${ctx.c.processTemplateId?processAnalysisView(ctx):''}${panel('Process actions','Enter the actual method. Sequence, timing, dependencies, and recovery remain editable.',`<div class="process-summary"><div><b>${c.actions.length}</b><span>actions</span></div><div><b>${number(c.actions.reduce((sum,a)=>sum+(a.seconds||0)*(a.frequency||0),0))} s</b><span>human work per unit</span></div><div><b>${r.automatedActions??0}</b><span>machine-assigned actions</span></div><div><b>${r.coveragePct==null?'—':number(r.coveragePct)+'%'}</b><span>baseline time assigned to technology</span></div></div><div class="process-map">${c.actions.map((a,i)=>{const actor=s.assignments[a.id],v=ctx.w.configs.find(v=>v.id===actor);return `<button class="action-node ${actor?'machine':''}" data-action="edit-action" data-id="${h(a.id)}"><div><span>${String(i+1).padStart(2,'0')}</span>${icon(actor?'robot':'person')}</div><strong>${h(a.name)}</strong><small>${number(a.seconds)} s × ${number(a.frequency)} · ${h(a.skill)}</small><span class="actor-label">${h(v?.name||'Human')}</span></button>`;}).join('')}</div>`,`${button('Paste actions','paste-actions',{iconName:'file'})}${button('Import actions','import-actions',{iconName:'file'})}${button('Add action','new-action',{kind:'primary',iconName:'plus'})}<input id="actions-import" type="file" accept=".csv,.json,.txt" hidden>`)}${panel('Action detail','The human time is active work. It is not always the total elapsed process time.',table(['# / action','Skill','Human time','Needs','Source','Dependency / recovery',''],c.actions.map((a,i)=>row([`<strong>${i+1}. ${h(a.name)}</strong><small>${h(a.taskGroup||'Task group not set')} · ${h(a.timingMethod||'Timing method not set')}</small><small>${h(a.note)}</small>`,h(a.skill),`${number(a.seconds)} s × ${number(a.frequency)}`,`${number(a.payloadKg)} kg · ${number(a.reachM)} m reach<br>${number(a.aisleM)} m aisle`,chip(a.source),`<small>${h(c.actions.find(x=>x.id===a.dependency)?.name||'Start')}${a.parallel?' · Parallel':''}</small>${h(a.recovery)}`,button('Edit','edit-action',{id:a.id})]))))}<div class="callout"><span>${icon('person')}</span><div><strong>Partial augmentation changes the method.</strong><p>Keep scanning, carrier exchange, support, and recovery work with a named actor. Splitting a load-handling bundle needs a valid handoff method. Recorded parallel work requires a more detailed resource model.</p></div></div>`;
}

function matchesView(ctx) {
  const c = ctx.c, s = selected(ctx), matchConfigs=ctx.w.configs.filter(v=>!c.processTemplateId||v.realProduct);
  const matchRows = c.actions.map(a => row([
    `<strong>${h(a.name)}</strong><small>${number(a.seconds)} s · ${h(a.skill)}</small>`,
    ...matchConfigs.map(v => {
      const f = fitAction(a, v);
      return `<button class="fit-cell ${f.status}" data-action="fit-detail" data-id="${h(a.id)}" data-config="${h(v.id)}" aria-label="${h(a.name)}: ${h(v.name)}: ${f.status}">${icon(f.status === 'fit' ? 'check' : f.status === 'blocked' ? 'close' : 'file')}<span>${f.status === 'fit' ? 'Fits inputs' : f.status === 'blocked' ? 'Blocked' : 'Unknown'}</span></button>`;
    })
  ]));
  const assignedRows = c.actions.map(a => {
    const actor = s.assignments[a.id] || 'human';
    const f = actor === 'human' ? null : fitAction(a, ctx.w.configs.find(v => v.id === actor));
    return row([
      `<strong>${h(a.name)}</strong>`,
      `<select data-assignment="${h(a.id)}" aria-label="Actor for ${h(a.name)}">${safeOptions([['human', 'Human'], ...matchConfigs.map(v => [v.id, v.name])], actor)}</select>`,
      f ? chip(f.status === 'fit' ? 'Fits recorded inputs' : f.status, f.status === 'fit' ? 'green' : 'amber') : chip('Human')
    ]);
  });
  const toolbar = `<div class="toolbar">${scenarioPicker(ctx)}${button(c.processTemplateId?'Update capability drafts':'Generate matched options',c.processTemplateId?'analyse-process':'generate-options',{kind:'primary',iconName:'layers'})}<div class="legend"><span class="fit-dot green-dot"></span>Fit to recorded inputs<span class="fit-dot red-dot"></span>Blocked<span class="fit-dot amber-dot"></span>Unknown</div></div>`;
  const matrix = panel('Action-to-technology match', 'Check each hard requirement. A commercial score cannot cancel a failed physical constraint.', table(['Action / human time', ...matchConfigs.map(v => v.name)], matchRows, 'match-matrix'));
  const assignment = panel('Assign the work', 'Edit the selected option. Blocked or unknown assignments remain drafts and cannot support an evaluation.', table(['Action', 'Assigned actor', 'Model status'], assignedRows), button('View team and fleet', 'case-tab', { id: 'Scenarios', kind: 'primary', iconName: 'arrow' }));
  return toolbar + assignmentFlowView(ctx) + matrix + assignment + `<div class="callout subtle"><div><strong>Skills belong to a complete configuration.</strong><p>The skill alone does not establish capability. Payload, reach, route, tool, software, task time, conditions, and evidence must also fit.</p></div></div>`;
}

export function assignmentFlowView(ctx,scenario=selected(ctx),result=evaluateScenario(ctx.c,scenario,ctx.w.configs)) {
 const c=ctx.c,configs=ctx.w.configs,groups=[...new Set(c.actions.map(a=>a.activityId||a.taskGroup||a.id))];
 const activities=groups.map((key,i)=>{
  const actions=c.actions.filter(a=>(a.activityId||a.taskGroup||a.id)===key);
  const rows=actions.map(action=>({action,actor:scenario.assignments[action.id]||'human',result:result.actionRows?.find(r=>r.id===action.id)}));
  const actors=[...new Set([...rows.map(r=>r.actor),...rows.filter(r=>configs.find(v=>v.id===r.actor)?.requiresOperator).map(()=>'human')])],human=actors.includes('human');
  const seconds=result.valid&&rows.every(r=>Number.isFinite(r.result?.seconds))?rows.reduce((n,r)=>n+r.result.seconds,0):null;
  return {id:`assignment-${scenario.id}-${i}`,index:i+1,name:actions[0].taskGroup||actions[0].name,rows,status:(actors.length===1?(human?'Human':configs.find(v=>v.id===actors[0])?.name||'Unknown technology'):human?'Human / technology split':'Multiple technologies')+(seconds==null?' · time not established':` · ${number(seconds)} s/output unit`),tone:human?'amber':'green',actors,seconds};
 });
 const human=activities.filter(a=>a.actors.every(x=>x==='human')).map(a=>a.index),technology=activities.filter(a=>!a.actors.includes('human')).map(a=>a.index),shared=activities.filter(a=>a.actors.includes('human')&&a.actors.length>1).map(a=>a.index);
 const assignmentRows=a=>a.rows.map(r=>{const v=configs.find(v=>v.id===r.actor);return `<div class="step-action"><strong>${h(r.action.workElement||r.action.name)}</strong><div class="capability-tags">${(r.action.requiredCapabilities||[r.action.skill]).filter(Boolean).map(x=>`<span>${h(x)}</span>`).join('')}</div><span class="step-actor ${r.actor==='human'?'human':'candidate'}">${h(r.actor==='human'?'Human':v?.name||'Unknown technology')}${v?.requiresOperator?' · human operator required':''}</span><small>${result.valid?number(r.result?.seconds)+' s/output unit':'Timing not established'} · ${h(r.actor==='human'?r.action.source||'Unknown':v?.source||'Unknown')}<br>${r.actor==='human'?'Retained work in this option.':'Assignment in the selected option. Check fit, tool, conditions, and complete bundle.'}</small></div>`;}).join('');
 return panel('Process work split',`${c.name} · ${scenario.name} · ${result.valid?'planning model result':'draft assignment; productivity is not established'}`,`${resultStatus(result)}<div class="work-split-summary"><span><i class="amber-key"></i><strong>Human steps</strong> ${human.join(', ')||'None'}</span><span><i class="green-key"></i><strong>Technology steps</strong> ${technology.join(', ')||'None'}</span>${shared.length?`<span><strong>Shared steps</strong> ${shared.join(', ')}</span>`:''}</div><div class="split-performance"><div><strong>${result.valid?number(result.capacity)+' /h':'Not established'}</strong><small>Whole-process capacity</small></div><div><strong>${result.valid?number(result.humanSeconds)+' s/unit':'Not established'}</strong><small>Human work with handoffs and recovery</small></div><div><strong>${result.valid?number(result.peoplePerShift):'Not established'}</strong><small>People per shift</small></div></div><div class="engineering-toolbar"><p class="engineering-hint">Step times are work content per output unit. They are not fleet throughput. Sample inputs remain sample evidence.</p><button class="button quiet" data-action="expand-process-activities">Expand all steps</button></div>${compactProcessFlow(activities,assignmentRows)}`);
}

function simulationView(ctx) {
 const c=ctx.c,study=c.study||{settings:{},benchmarks:[],requests:[]},settings=study.settings;
 const records=study.benchmarks||[];
 return `<div class="page-heading compact"><div><h1>AWS deployment plan</h1><p>Additional AWS workstream · September 2026 prototype scope · simulation phase · plan v${study.revision||1}</p></div><div class="action-group"><label class="inline-label">Evaluation case<select data-action="select-case" aria-label="AWS plan case">${safeOptions(ctx.w.cases.map(c=>[c.id,c.name]),c.id)}</select></label>${button('Export study package','study-export',{kind:'primary',iconName:'file'})}</div></div><div class="scope-framework">${['Sense · capture','Decide · compare','Simulate · task + process','Execute · simulation only'].map((x,i)=>`<span><b>${i+1}</b>${x}</span>`).join('')}</div><div class="callout subtle"><div><strong>AWS plan: simulation prototype and external-service preparation</strong><p>This workstream supports the current evaluation and deployment workflow. It does not add a mandatory case stage. Isaac Sim, Isaac Lab, SimPy, Mimic, and LeRobot execution need external services. A prepared request does not start a GPU job. Physical robot deployment and production WMS/LMS integration are outside this scope.</p></div></div><div class="study-stage-grid">${STUDY_STAGES.map(([id,title,scope,stack,fields],i)=>`<details class="study-stage" data-study-stage="${id}" ${id==='benchmark'?'open':''}><summary><span class="activity-index">${i+1}</span><span><strong>${h(title)}</strong><small>${h(stack)}</small></span>${chip(scope,scope==='Stretch'?'purple':'')}<span class="study-request-count">${study.requests.filter(r=>r.stage===id).length} requests</span></summary><div class="study-stage-body">${gridFields(fields.map(([key,label])=>noteField(`study.settings.${key}`,label,settings[key]||'')))}<div class="toolbar"><small>Values are local configuration notes. Runtime validation belongs to the external runner.</small>${button('Save configuration','study-save',{id})}${button('Prepare request','study-request',{id,iconName:'file'})}</div>${id==='benchmark'?button('Record benchmark result','study-benchmark',{kind:'primary',iconName:'plus'}):''}</div></details>`).join('')}</div>${panel('Robot benchmark comparison','Compare only records with the same protocol, task, scene, conditions, and evidence class. Case or AWS plan changes require a new review.',records.length?table(['Robot / policy','Protocol / task / scene','Evidence / revision','First-pass success','Mean task cycle','Interventions / recovery','Comparison'],records.map(b=>{const comparable=records.filter(x=>benchmarkKey(x)===benchmarkKey(b)&&x.caseRevision===c.revision&&(x.studyRevision||1)===(study.revision||1));return row([`<strong>${h(ctx.w.configs.find(v=>v.id===b.configId)?.name||b.configId)}</strong><small>${h(b.policyKind)} · ${h(b.policy)}</small>`,`<strong>${h(b.protocol)}</strong><small>${h(b.taskVersion)} · ${h(b.sceneVersion)}</small><small>${h(b.conditions)}</small>`,`${chip(b.evidence,b.evidence==='Sample'?'amber':'')}<small>Case v${b.caseRevision} / AWS plan v${b.studyRevision||1}${b.caseRevision!==c.revision||(b.studyRevision||1)!==(study.revision||1)?' · out of date':''}</small>`,`${number(100*b.successes/b.attempts)}%<small>${b.successes}/${b.attempts} episodes</small>`,`${number(b.cycleSec)} s<small>Task cycle; not process throughput</small>`,`${number(b.interventions,0)} / ${number(b.recoverySec)} s<small>Energy: ${number(b.energyKwh)} kWh</small>`,`${b.caseRevision===c.revision&&(b.studyRevision||1)===(study.revision||1)&&comparable.length>1?chip('Common comparison group','green'):chip('Needs comparable record','amber')}<small>${h(b.source)}</small>`]);})):empty('No benchmark results','Record an external result or a clearly labelled sample. No run is implied.'),button('Record benchmark result','study-benchmark',{iconName:'plus'}))}${panel('Prepared requests','These are local preparation records. They are not submitted, queued, or completed jobs.',study.requests.length?table(['Stage','Status','Case revision','Date'],study.requests.map(r=>row([h(STUDY_STAGES.find(s=>s[0]===r.stage)?.[1]),chip(r.status),String(r.caseRevision),h(r.date)]))):empty('No requests prepared','Complete a stage configuration, then prepare its request.'))}${panel('Use results in the business case','External results do not change product records or economic inputs automatically.',`<p>Review the task boundary, version, conditions, and distribution. Map approved timing evidence to the exact action or complete work bundle in Matches and the technology record. Record charge, downtime, recovery, and cost separately. Re-evaluate the whole process before a recommendation.</p><div class="action-group">${button('Review work assignment','case-tab',{id:'Matches'})}${button('Open business case','case-tab',{id:'Results',kind:'primary'})}</div>`)}`;
}

function scenariosView(ctx) {
  const c=ctx.c,s=selected(ctx),r=selectedResult(ctx),results=evaluateCase(c,ctx.w.configs);
  const used=[...new Set(Object.values(s.assignments||{}).filter(id=>id!=='human'))];
  return `<div class="toolbar">${scenarioPicker(ctx)}<div class="action-group">${button('Duplicate option','duplicate-scenario',{iconName:'plus'})}${button('New option','new-scenario',{iconName:'plus'})}${button(c.processTemplateId?'Update capability drafts':'Generate matched options',c.processTemplateId?'analyse-process':'generate-options',{kind:'primary',iconName:'layers'})}</div></div><div class="two-columns">${panel('Team and fleet','Size the machines for the work they perform.',used.length?`<div class="fleet-inputs">${used.map(id=>{const v=ctx.w.configs.find(v=>v.id===id);return `<div class="fleet-input"><div class="fleet-icon">${icon('robot')}</div><div><strong>${h(v?.name||id)}</strong><small>${h(v?.source)} · complete configuration</small></div><label>Units<input type="number" min="1" max="100" step="1" data-count="${h(id)}" value="${s.counts[id]??1}" aria-label="Fleet count for ${h(v?.name||id)}"></label></div>`;}).join('')}</div>`:empty('No machines assigned','Keep the manual comparison or assign work in Matches.'),button('Compare fleet counts','fleet-search',{kind:'primary',iconName:'search',extra:used.length?'':'disabled'}))}${panel('Modelled process performance','Peak demand and the bottleneck limit the whole process.',`<div class="result-status">${resultStatus(r)}</div><dl class="definition-list"><div><dt>Average / peak demand</dt><dd>${number(r.avgHour)} / ${number(r.peakHour)} units/h</dd></div><div><dt>Process capacity</dt><dd>${number(r.capacity)} units/h</dd></div><div><dt>Required people</dt><dd>${number(r.peoplePerShift)} per shift</dd></div><div><dt>Remaining human work</dt><dd>${number(r.humanSeconds)} s/unit</dd></div><div><dt>Handoffs / recovery</dt><dd>${r.handoffs??'—'} transitions · ${number(r.recoverySeconds)} s/unit recovery</dd></div><div><dt>Bottleneck</dt><dd>${h(r.bottleneck||'Complete the inputs')}</dd></div></dl>`)}</div>${r.errors.length?panel('Inputs or constraints to resolve','The app has not calculated a valid result.',`<ul class="error-list">${r.errors.map(e=>`<li>${h(e)}</li>`).join('')}</ul>`):''}${r.fleet.length?panel('Resource capacity','Charge and downtime are disjoint shares of the same operating window. A single retry is allowed in this screening model.',table(['Configuration','Count / required bound','Work + retry time','Usable window','Capacity','Source'],r.fleet.map(f=>row([h(f.name),`${f.count} / ${f.required??'—'}`,`${number(f.busySeconds)} + ${number(f.retrySeconds-f.busySeconds)} s`,`${number(f.usablePct)}%`,`${number(f.rate)} units/h`,chip(f.source)])))):''}${panel('Options in this case','Current and improved manual methods remain in the comparison.',table(['Option','Status','People / shift','Machines','Capacity','Annual net',''],results.map(x=>row([`<strong>${h(x.name)}</strong>`,resultStatus(x),number(x.peoplePerShift),String(x.fleet.reduce((sum,f)=>sum+f.count,0)),`${number(x.capacity)} /h`,euro(x.annualNet),button('Select','choose-scenario',{id:x.id,kind:c.selectedScenarioId===x.id?'primary':'secondary'})]))))}${panel('Search scope and limits','The fleet search tests one to six units per assigned configuration, with up to three configurations.',`<p>Changing fleet count can remove a machine bottleneck. It does not remove remaining human actions or prove traffic, charge scheduling, safe handoffs, or performance at the site. The app reports every tested count and its status.</p>`)}`;
}

function cashChart(result) {
  if (!result.valid) return empty('Cash flow is not available','Complete the inputs and constraints.');
  const points=[{year:0,cumulative:-result.upfront},...result.cashflows], max=Math.max(1,...points.map(p=>Math.abs(p.cumulative))), w=640,hgt=215, x=i=>36+i*(w-72)/(points.length-1), y=v=>105-v/max*75;
  return `<svg viewBox="0 0 ${w} ${hgt}" class="cash-chart" role="img" aria-label="Cumulative incremental cash flow in EUR"><line x1="30" x2="615" y1="105" y2="105" stroke="#c5d6d0" stroke-dasharray="4 5"/><text x="8" y="100" fill="#61756e" font-size="11">0</text><path d="${points.map((p,i)=>`${i?'L':'M'}${x(i)},${y(p.cumulative)}`).join(' ')}" fill="none" stroke="#177860" stroke-width="3"/>${points.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.cumulative)}" r="4" fill="#177860"/><text x="${x(i)}" y="${y(p.cumulative)+(p.cumulative<0?20:-12)}" text-anchor="middle" fill="#264d40" font-size="11">${Math.round(p.cumulative/1000)}k</text><text x="${x(i)}" y="200" text-anchor="middle" fill="#61756e" font-size="11">Year ${p.year}</text>`).join('')}</svg>`;
}

function resultsView(ctx) {
  const c=ctx.c,s=selected(ctx),r=selectedResult(ctx),rec=recommendCase(c,ctx.w.configs),currentDecision=c.decision?.revision===c.revision&&c.decision.result?.modelVersion===MODEL_VERSION;
  return `<div class="toolbar">${scenarioPicker(ctx)}${button('Export recommendation','report',{iconName:'file'})}</div>${assignmentFlowView(ctx)}<div class="recommendation"><div class="recommendation-icon">${icon('brief')}</div><div><small>RECOMMENDATION / TESTED SET</small><h2>${rec.best?h(rec.best.name):'No supported candidate'}</h2><p>${h(rec.text)}</p></div><div>${rec.best&&rec.best.id!==s.id?button('Use best candidate','choose-scenario',{id:rec.best.id,kind:'primary'}):''}${chip(rec.best?'Next: evidence study':'Next: revise or collect data',rec.best?'green':'amber')}</div></div><div class="metrics">${metric('Annual net cash saving',euro(r.valid?r.annualNet:null),'Steady year · check the horizon and NPV',r.annualNet>0?'green':'','brief')}${metric('Upfront cash',euro(r.valid?r.upfront:null),'Hardware + integration + site changes','','layers')}${metric('Payback',r.valid?(r.payback!=null?`${number(r.payback)} years`:'No payback'):'Not known',r.valid?'Within the entered study horizon':'Inputs or evidence are missing','','clock')}${metric('Process cost per good unit',r.costPerUnit==null?'Not known':unitEuro(r.costPerUnit),'Annual staffing + added cost + spread upfront','','activity')}</div>${r.errors.length?panel('Result unavailable','Resolve these items before you use financial outputs.',`<ul class="error-list">${r.errors.map(x=>`<li>${h(x)}</li>`).join('')}</ul>`):''}<div class="two-columns">${panel('From work time to cash','Each step has a separate meaning.',`<div class="benefit-bridge">${[['Baseline time assigned to machines',r.coveragePct==null?'—':`${number(r.coveragePct)}%`,'A time share, not an employee count.'],['Remaining human work',`${number(r.humanSeconds)} s/unit`,'Includes handoffs, support at assist tools, and recovery.'],['Potential positions released',`${number(r.potentialFte)} annual FTE`,'From a whole-shift staffing calculation.'],['Positions with cash benefit',`${number(r.cashFte)} annual FTE`,c.economics.benefitMode],['Retained labour benefit',euro(r.capturedLaborBenefit),`${number(c.economics.retainedPct)}% retained in this viewpoint.`],['Added annual cost',euro(r.annualAddedCost),'Robot service, energy, software, site support, and any extra staffing.']].map(([label,value,help],i)=>`<div><span class="bridge-index">${i+1}</span><div><strong>${label}</strong><small>${h(help)}</small></div><b>${h(value)}</b></div>`).join('')}</div>`)}${panel('Cumulative cash flow','Upfront cash is paid at year zero. The first year includes the entered ramp-up.',cashChart(r)+`<div class="mini-stats"><div><b>${euro(r.valid?r.npv:null)}</b><span>NPV · ${number(c.economics.discountPct)}% scenario rate</span></div><div><b>${euro(r.valid?r.lifetimeNet:null)}</b><span>Net cash over ${number(c.economics.horizonYears,0)} years</span></div></div>`)}</div><div class="evidence-grid">${panel('Technical fit',r.meetsDemand&&r.meetsQuality?'Requirements met in this model':'Review the capacity or quality gap',`<strong class="status-value">${r.valid&&r.meetsDemand&&r.meetsQuality?'Conditional fit':'Not established'}</strong><p>Fit applies to the recorded configuration, task bundle, and operating assumptions.</p>`)}${panel('Performance evidence',r.evidence||'Not established',`<strong class="status-value amber-text">${h(r.evidence||'Data needed')}</strong><p>No calibrated probability is available. Supplier data, simulation, and field tests need a stated validity range.</p>`)}${panel('Economic robustness','Check the adverse scenarios below.',`<strong class="status-value">${r.breakEvenCapturePct==null?'Not known':`${number(r.breakEvenCapturePct)}% capture`}</strong><p>Simple steady-year break-even labour-benefit capture. It does not prove payback within the contract.</p>`)}</div>${panel('Scenario stress test','These are named assumptions, not probabilities.',table(['Scenario','Process status','Required people / shift','Capacity','Annual net','Payback'],stressScenario(c,s,ctx.w.configs).map(x=>row([h(x.stressName),resultStatus(x),number(x.peoplePerShift),`${number(x.capacity)} /h`,euro(x.valid?x.annualNet:null),x.valid&&x.payback!=null?`${number(x.payback)} years`:'No payback']))))}${panel('Cash-flow detail','Cash costs are separate from accounting depreciation.',table(['Year','Captured benefit','Added cost','Net cash','Cumulative'],[{year:0,benefit:r.valid?0:null,cost:r.upfront,net:r.upfront==null?null:-r.upfront,cumulative:r.upfront==null?null:-r.upfront},...r.cashflows].map(x=>row([String(x.year),euro(x.benefit),euro(x.cost),euro(x.net),euro(x.cumulative)]))))}${panel('Record the next decision','This records a local planning decision. It does not authorize a robot or a site pilot.',`<div class="decision-summary">${c.decision?`<div>${chip(currentDecision?'Current decision':'Out of date',currentDecision?'green':'amber')}<strong>${h(c.decision.outcome)}</strong><p>${h(c.decision.reason)}</p><small>${h(c.decision.owner)} · Case v${c.decision.revision}</small></div>`:'<p>No decision has been recorded for this version.</p>'}${button('Record decision','record-decision',{kind:'primary',iconName:'check'})}</div>`)}${panel('Model limits and warnings','Keep these with the recommendation.',`<ul class="warning-list">${r.warnings.map(x=>`<li>${h(x)}</li>`).join('')}<li>The staffing plan is a planning bound. Minimum coverage, time fragments, and shared work must be checked at the site.</li><li>All sample evidence remains sample evidence, even when the cash result is positive.</li></ul>`)}`;
}

function deploymentView(ctx) {
  const c=ctx.c,d=c.deployment,ready=readiness(c,ctx.w.configs),checked=DEPLOY_CHECKS.filter(([key])=>d.checklist[key]).length;
  return `<div class="deployment-heading"><div><h2>Deployment plan</h2><p>Hardware, software, tests, and assigned responsibilities.</p></div>${chip(`${ready.gaps.length} open readiness items`,'amber')}</div><div class="deployment-path">${['Plan','Configure / train','Test release','Prepare site','Supervised pilot','Operate / improve'].map((t,i)=>`<div><span>${i+1}</span><strong>${t}</strong></div>`).join('')}</div><div class="two-columns">${panel('Execution and release plan','Use OEM commissioning, policy/model adaptation, or both. AWS and the OEM must define the supported route.',gridFields([
    selectField('deployment.route','Execution route',d.route,['OEM configuration','Policy / model adaptation','OEM configuration + policy adaptation','To be defined']),inputField('deployment.target','Target hardware and tool',d.target,{type:'text'}),inputField('deployment.release','Release / model / policy version',d.release,{type:'text'}),inputField('deployment.supportOwner','Accountable delivery / support owner',d.supportOwner,{type:'text'}),noteField('deployment.siteNotes','Site preparation and operating limits',d.siteNotes),noteField('deployment.interfaceNotes','Interfaces and recovery method',d.interfaceNotes),noteField('deployment.trainingNotes','Data and training plan, if required',d.trainingNotes,'Name datasets, labels, simulation assets, supported stack, test cases, and expected outputs.'),noteField('deployment.rollback','Fallback and rollback version',d.rollback),noteField('deployment.pilotNotes','Pilot measures and stop rules',d.pilotNotes)
  ]))}${panel('Readiness review','Review items are local records. They do not certify the installation.',`<div class="readiness-progress"><b>${checked}<span>/ 8</span></b><div><strong>Review items recorded</strong>${progress(checked/8*100)}</div></div><div class="check-list">${DEPLOY_CHECKS.map(([key,title,detail])=>`<label><input type="checkbox" data-check="${key}" ${d.checklist[key]?'checked':''}><span><strong>${title}</strong><small>${detail}</small></span></label>`).join('')}</div>`,button('Review readiness','review-readiness',{kind:'primary',iconName:'check'}))}</div>${panel('External service plan','These adapters are not connected. Use them to define the work and output contract.',`<div class="adapter-grid">${[['CAD / environment','Layout, objects, dimensions, and material properties','Mapped model + assumptions + validation issues'],['Process / physics','Versioned process, configuration, task conditions, and test cases','Times, successes, failures, recovery, samples, and limits'],['Training / policy','Supported stack, data, task definitions, tests, and compute','Versioned policy/model + metrics + failure tests'],['Hardware transfer','Approved release, supported hardware, site tests, and fallback','Transfer record + checks + supervised pilot observations']].map(([name,input,output])=>`<div class="adapter-card"><div class="card-top"><strong>${name}</strong>${chip('Not connected')}</div><small>INPUT</small><p>${input}</p><small>REQUIRED OUTPUT</small><p>${output}</p>${button('Prepare request','adapter-request',{id:name,kind:'text',iconName:'file'})}</div>`).join('')}</div>`)}${panel('Test and pilot records','Every test links to a case version. A material change requires a new test.',d.testResults.length?table(['Test','Result','Source / notes','Case version',''],d.testResults.map(t=>row([h(t.name),chip(t.status,t.status==='Pass'?'green':'amber'),`<strong>${h(t.source)}</strong><small>${h(t.note)}</small>`,chip(`v${t.revision}${t.revision===c.revision?'':' · out of date'}`,t.revision===c.revision?'':'amber'),h(t.date)]))):empty('No tests recorded','Define the task, conditions, source, result, and remaining limits.'),button('Add test record','new-test',{iconName:'plus'}))}${panel('Assets planned for this process','Keep intended, pilot, and operating assets separate.',d.assets.length?table(['Asset','Configuration','Release','Status',''],d.assets.map(a=>row([h(a.name),h(ctx.w.configs.find(v=>v.id===a.configId)?.name||a.configId),h(a.release),chip(a.status),button('Edit','edit-asset',{id:a.id,extra:`data-case="${h(c.id)}"`})]))):empty('No planned assets','Create an asset record from the selected option or add one by hand.'),`${button('Add asset','add-asset',{iconName:'plus'})}${button('Create planned fleet','plan-fleet',{kind:'primary',iconName:'robot'})}`)}`;
}

function learningView(ctx) {
  const c=ctx.c,r=selectedResult(ctx), observations=c.observations.map(o=>({...o,metrics:observationMetrics(o)}));
  return `<div class="page-heading compact"><div><h2>Learn from the actual work.</h2><p>Use a defined observation window. Compare demand, output, quality, human work, and cost.</p></div><div class="action-group">${button('Import observations','import-observations',{iconName:'file'})}${button('Add observation','new-observation',{kind:'primary',iconName:'plus'})}<input type="file" id="observations-import" accept=".csv" hidden></div></div><div class="metrics">${metric('Observation records',String(observations.length),'Sample and measured records stay distinct','','file')}${metric('Expected process rate',`${number(r.capacity)} /h`,'Planning capacity · peak screening model','','activity')}${metric('Expected human work',`${number(r.humanSeconds)} s/unit`,'Retained actions + handoff + recovery','','person')}${metric('Open issues',String(c.issues.filter(i=>i.status!=='Closed').length),'Assign a next action and owner','amber','layers')}</div>${panel('Expected versus observed','Observed output depends on supplied demand. A lower rate alone does not prove lower robot capacity.',observations.length?table(['Window / source','Good output','Good-unit share','Interventions','Human work','Cost / good unit','Follow-up'],observations.map(o=>row([`<strong>${h(o.date)} · ${number(o.hours)} h</strong><small>${h(o.source)}</small>${chip(o.status,o.status==='Measured'?'green':'')}`,`${number(o.metrics.goodUnits,0)} units<small>${number(o.metrics.goodUph)} /h</small>`,o.metrics.qualityPct==null?'—':`${number(o.metrics.qualityPct)}%`,`${number(o.metrics.interventionsPer1000)} /1k`,`${number(o.metrics.humanHoursPer1000)} h/1k`,o.metrics.costPerUnit==null?'—':`${unitEuro(o.metrics.costPerUnit)}`,button('Open issue','observation-issue',{id:o.id})]))):empty('No observations yet','Enter measured or sample trial data. No live telemetry is connected.'))}${panel('Issues and improvement work','Revise the process or configuration, then test the new version.',c.issues.length?table(['Issue','Owner','Status','Action / evidence',''],c.issues.map(i=>row([`<strong>${h(i.title)}</strong><small>${h(i.date)}</small>`,h(i.owner),chip(i.status,i.status==='Closed'?'green':'amber'),h(i.note),button('Edit','edit-issue',{id:i.id})]))):empty('No issues recorded','Record performance gaps, failures, interface problems, and the next test.'),button('Add issue','new-issue',{iconName:'plus'}))}<div class="callout subtle"><span>${icon('activity')}</span><div><strong>Review the evidence before you change the model.</strong><p>A new observation can support a revised task time or failure rate. Record its conditions and source in the technology library. Then evaluate a new case version. This app does not automatically retrain or load hardware.</p></div></div>`;
}

export function renderReport(c, configs) {
  const scenario=c.scenarios.find(s=>s.id===c.selectedScenarioId)||c.scenarios[0], r=evaluateScenario(c,scenario,configs),rec=recommendCase(c,configs),ready=readiness(c,configs);
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${h(c.name)} — recommendation</title><style>body{font:15px/1.6 'Segoe UI',Arial;color:#183d33;max-width:1000px;margin:40px auto;padding:0 25px}h1{font-size:26px}h2{margin-top:28px}.engineering-symbol{width:24px;height:24px}.compact-flow-head{display:none}.engineering-step{border:1px solid #ddd;padding:9px;margin:6px 0}.engineering-step summary{display:flex;align-items:center;gap:10px;font-size:12px}.compact-step-title{min-width:180px}.compact-step-title strong{display:block}.atomic-preview{display:flex;flex-direction:column;font-size:11px}.atomic-preview b{margin-right:8px}.engineering-actions{font-size:12px;padding:12px}.step-action{border-top:1px solid #ddd;padding:8px}.capability-tags span{margin-right:8px}.work-split-summary{font-size:12px}.work-split-summary>span{display:block}.split-performance{display:flex;gap:25px;font-size:12px;margin:15px 0}.compact-expand,.engineering-toolbar button{display:none}small{display:block;color:#60766e}.banner{background:#f2f5ec;padding:15px;border-left:4px solid #ae9c3d}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:10px;border-bottom:1px solid #d6e0da;vertical-align:top}th{background:#edf4ef}.chip{font-size:12px}footer{margin-top:35px;border-top:1px solid #ccc;padding-top:15px}@media print{body{margin:0}tr{break-inside:avoid}}</style></head><body><small>HYBRID WORKFORCE · PLANNING REPORT · ${new Date().toISOString().slice(0,10)}</small><h1>${h(c.name)}</h1><p>${h(c.site)} · ${h(c.country)} · Case v${c.revision} · ${h(r.modelVersion)}</p><div class="banner">${c.sample?'Sample inputs. ':''}Planning result. No live simulation, robot training, certification, or hardware deployment is performed by this prototype.</div><h2>Recommendation</h2><p>${h(rec.text)}</p><p>Best candidate in the tested set: <strong>${h(rec.best?.name||'None')}</strong>. Selected option: <strong>${h(scenario.name)}</strong>. Status: ${h(r.status)}.</p><h2>Business case</h2>${table(['Measure','Result'],[['Demand',`${number(c.baseline.demandDaily)} units/day · ${number(r.peakHour)} peak units/h`],['Capacity',`${number(r.capacity)} units/h`],['Human staffing',`${number(r.peoplePerShift)} people/shift · ${number(r.scenarioFte)} annual positions`],['Potential / cash-benefit positions',`${number(r.potentialFte)} / ${number(r.cashFte)}`],['Benefit mode',h(c.economics.benefitMode)],['Annual net cash saving',euro(r.valid?r.annualNet:null)],['Upfront cash',euro(r.valid?r.upfront:null)],['Payback',r.valid&&r.payback!=null?`${number(r.payback)} years`:'No supported payback'],['NPV',`${euro(r.valid?r.npv:null)} · ${c.economics.discountPct}% assumed discount rate`],['First-pass quality',r.quality==null?'Not known':`${number(r.quality)}% · model input basis`],['Performance evidence',h(r.evidence||'Missing')]].map(row))}<h2>Process work split</h2>${assignmentFlowView({c,w:{configs}},scenario,r)}<h2>Work assignment</h2>${table(['Action','Actor','Baseline seconds','Option seconds'],(r.actionRows||[]).map(a=>row([h(a.name),h(configs.find(v=>v.id===a.actor)?.name||'Human'),number(a.humanBaselineSeconds),number(a.seconds)])))}<h2>Fleet</h2>${table(['Configuration','Count','Required planning bound','Evidence'],r.fleet.map(f=>row([h(f.name),String(f.count),String(f.required??'Unknown'),h(f.source)])))}<h2>Cash flow</h2>${table(['Year','Benefit','Added cost','Net','Cumulative'],r.cashflows.map(y=>row([String(y.year),euro(y.benefit),euro(y.cost),euro(y.net),euro(y.cumulative)])))}<h2>Conditions and limits</h2><ul>${[...r.errors,...r.warnings,'The search is bounded. It does not prove a global optimum.','Task-count coverage is not labour or cash savings.','The confidence probability is not calibrated. Review the sources and adverse scenarios.'].map(x=>`<li>${h(x)}</li>`).join('')}</ul><h2>Deployment path</h2><p>${h(c.deployment.route)}. Target: ${h(c.deployment.target)}. Release: ${h(c.deployment.release)}.</p><ul>${ready.gaps.map(x=>`<li>${h(x)}</li>`).join('')}</ul><h2>Source register</h2>${table(['Source','Status','Date','Notes'],c.sources.map(s=>row([h(s.name),h(s.status),h(s.date),h(s.note)])))}<h2>Recorded decision</h2><p>${c.decision?`${h(c.decision.outcome)} · ${h(c.decision.owner)} · Case v${c.decision.revision}. ${h(c.decision.reason)}`:'No planning decision recorded.'}</p><footer>Prepared locally. All figures depend on the entered assumptions and evidence. Retained business benefit is separate from total automation value.</footer></body></html>`;
}

function inputRegister(ctx) {
  const records = ctx.c.inputGroups || {};
  return panel('Potential platform inputs', 'Record all 12 input groups. Blank fields mean not known. These context records do not feed calculations automatically.',
    `<div class="callout subtle"><p>Enter the values used by the model in the baseline, economics, Process, and Technology library fields. Keep their source records aligned. A status label does not verify the data.</p></div><div class="input-register">${INPUT_GROUPS.map(([id,name,fields,output,limit],index)=>{
      const r=records[id]||{}, path=`inputGroups.${id}`;
      const fieldsHtml=gridFields([
        selectField(`${path}.status`,'Data status',r.status||'Unknown',SOURCE_STATES),
        inputField(`${path}.owner`,'Input owner',r.owner||'',{type:'text'}),
        inputField(`${path}.capturedAt`,'Capture date and time',r.capturedAt||'',{type:'datetime-local'}),
        inputField(`${path}.validUntil`,'Valid until',r.validUntil||'',{type:'datetime-local'}),
        selectField(`${path}.sourceId`,'Linked source',r.sourceId||'',[['','No source linked'],...ctx.c.sources.map(x=>[x.id,x.name])]),
        inputField(`${path}.system`,'Source system or file reference',r.system||'',{type:'text'}),
        ...fields.map((label,i)=>noteField(`${path}.detail${i+1}`,label,r[`detail${i+1}`]||'')),
        noteField(`${path}.limits`,'Units, conditions, missing data, and validity limits',r.limits||'')
      ]).replaceAll('data-field=','data-input-key=');
      return `<details class="input-group"><summary><span>${String(index+1).padStart(2,'0')} · ${h(name)}</span>${chip(r.status||'Unknown',r.status==='Measured'?'green':'amber')}</summary><div class="input-group-body"><p><strong>Intended output:</strong> ${h(output)}</p><p class="muted">${h(limit)}</p>${fieldsHtml}<p class="muted">Save this input group before you leave the page.</p>${button('Save input group','save-input-group',{id,kind:'primary'})}</div></details>`;
    }).join('')}</div>`, button('View application flow','navigate',{id:'workflow',kind:'text',iconName:'arrow'}));
}

export function workflowView(ctx) {
  const branches = {2:'Enough evidence? No → record the gaps → collect data → return to inputs. Pause if data is not available.',3:'No valid match? Keep the manual method, change the work or technology, or stop. Return to the process and library.',4:'Capacity or quality fails? Change the fleet or work split → compare again. Stop if no feasible option remains.',5:'No economic case? Review benefit capture and cost → redesign or retain the manual method. Do not force a positive result.',6:'Proceed to an evidence study → prepare the tests. Collect data → return to inputs. Change the process → return to actions. Defer or stop → keep the reason.',7:'Readiness not established? Resolve each gap → repeat the review. A local record does not approve a real pilot.',8:'Pilot stop rule met? Stop the trial, use the agreed fallback, and return to preparation.',9:'Measured result differs? Open an issue → update the evidence and options → repeat the decision. Expand only after review.'};
  const steps = [
    ['Define the case','Set the site, process, owner, demand, and decision goal.','Inputs'],
    ['Describe the work','Break the process into actions. Add time, load, reach, dependencies, and recovery.','Process'],
    ['Check the evidence','Use the 12 input groups and source files. Confirm units, dates, conditions, and gaps.','Inputs'],
    ['Match actions and work bundles','Compare the demand with technology skills, limits, tools, and task performance.','Matches'],
    ['Build and compare options','Retain human work. Test fleet counts, handoffs, charging, downtime, and peak demand.','Scenarios'],
    ['Check the full business case','Separate time removed, staffing change, cash benefit, and benefit ownership. Compare cost and cash flow.','Results'],
    ['Record the decision','Study, collect data, change the process, defer, or stop. Evidence quality is not a probability score.','Results'],
    ['Prepare site delivery','Agree the OEM / AWS execution route. Record the release, interfaces, tests, support, safety review, and rollback plan.','Deployment'],
    ['Run a supervised pilot','A real pilot needs external systems and site approval. Record good output, failures, recovery, human work, and cost.','Learning'],
    ['Measure and improve','Compare the trial with its baseline. Update evidence, actions, technology data, and the business case. Review again.','Learning']
  ];
  return `<div class="page-heading"><div><h1>How it works</h1><p>Application stages, required inputs, decision points, and outputs.</p></div>${viewLink(ctx.c,'Inputs','Open case inputs')}</div>
    ${panel('Application flow','The arrows show the main path. Decision branches show where to return, pause, or stop.',`<nav class="flow-overview" aria-label="Flow overview">${steps.map(([name,,tab],i)=>viewLink(ctx.c,tab,`${i+1}. ${name} →`)).join('')}</nav><p class="muted">Missing evidence → collect data. Failed fit or value → redesign, keep manual work, defer, or stop. Pilot feedback → repeat the review.</p><ol class="workflow-chart">${steps.map(([name,description,tab],i)=>`<li><div class="flow-step"><span class="flow-number">${i+1}</span><div><h3>${h(name)}</h3><p>${h(description)}</p>${viewLink(ctx.c,tab,'Open '+tab.toLowerCase())}</div>${chip(i<7?'Local planning':i===7?'Local preparation':'External trial + local records',i<8?'green':'amber')}</div>${branches[i]?`<aside class="flow-branch">${h(branches[i])}</aside>`:''}</li>`).join('')}</ol>`)}
    ${panel('Input and output map','These are the intended platform outputs. The present prototype has the limits shown here.',table(['Potential input','What it contains','Intended output','Current support'],INPUT_GROUPS.map(([,name,fields,output,limit])=>row([h(name),h(fields.join('; ')),h(output),h(limit)]))))}
    ${panel('Functions that need external systems','This page defines the full journey. It does not claim those services are connected.',`<p>CAD interpretation, traffic simulation, model training, hardware release, live dispatch, sensor feeds, and predictive maintenance need separate services. The current app stores plans, source files, requests, review records, and observations.</p><p>Manufacturer data can support an initial assumption. The supported configuration and its validity range must be confirmed. AWS and the OEM must define when simulation or a physical test is needed.</p>`)}
  `;
}

function processStepSymbol(name) {
  const n=name.toLowerCase();
  const pallet='<path d="M12 43h48v7H12zm4 7v5m17-5v5m21-5v5M18 43V26l18-8 18 8v17M18 26l18 8 18-8M36 34v9M27 22l18 8"/>';
  const tote='<path d="M13 25h46l-5 25H18zm0 0v-6h46v6M26 32h20M24 39h24M28 19v-5h16v5"/>';
  const person='<circle cx="36" cy="16" r="7"/><path d="M26 54l3-19V28q7-7 14 0v7l3 19M29 30l-10 9m24-9 10 9M36 36v18"/>';
  const scanner='<path d="M23 12h28v24H23zm5 24-5 19h12l6-19M28 19h18m-18 6h18M12 13v18m4-18v18m43-18v18m4-18v18"/>';
  const box='<path d="M14 25l22-12 22 12v27l-22 9-22-9zm0 0 22 11 22-11M36 36v25M25 19l22 11"/>';
  const check='<path d="M21 14h30v44H21zm8-4h14v9H29M28 32l5 5 12-13M28 45h16M28 51h12"/>';
  const travel='<path d="M12 46h43v8H12zm8 0V28h24v18M24 28v-8h16v8M19 54v5m29-5v5M48 17h15m-5-5 5 5-5 5"/>';
  const label='<path d="M15 16h30l16 16-25 25-21-21zm9 10h1m9-1 16 16M29 30l16 16M24 35l16 16"/>';
  const clean='<path d="M16 27h30l-3 29H19zm-2-7h34M25 20v-7h13v7M26 33v16m10-16v16M53 13v18m-6-9h13"/>';
  const cover='<path d="M12 38l24-11 24 11-24 11zm0 8 24 11 24-11M36 10v12m-6-6 6-6 6 6"/>';
  const shape=/cover/.test(n)?cover:/debris|waste|scrap/.test(n)?clean:/label|tape/.test(n)?label:/scan|system|order|book/.test(n)?scanner:/check|inspect|verify|confirm/.test(n)?check:/walk|move|transport|bring|transfer|drive/.test(n)?travel:/pallet/.test(n)?pallet:/tote|klt|container/.test(n)?tote:/human|handover|register/.test(n)?person:box;
  return `<svg class="engineering-symbol" viewBox="0 0 72 72" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true">${shape}</svg>`;
}

function compactProcessFlow(activities,actionRows) {
 return `<div class="engineering-flow compact-process" aria-label="Activity flow"><div class="compact-flow-head"><span>Process step</span><span>Atomic actions</span></div>${activities.map(a=>`<details class="activity-breakdown engineering-step ${a.tone}" id="visual-${h(a.id)}"><summary><span class="compact-step-index">${String(a.index).padStart(2,'0')}</span>${processStepSymbol(a.name)}<span class="compact-step-title"><strong>${h(a.name)}</strong><small class="engineering-state ${a.tone}">${h(a.status)}</small></span><span class="atomic-preview">${a.rows.map((r,i)=>`<span><b>${i+1}</b>${h(r.action.workElement||r.action.name)}</span>`).join('')}</span><span class="compact-expand" aria-hidden="true">+</span></summary><div class="engineering-actions"><div class="compact-bundle"><strong>Handling group:</strong> ${h(a.rows[0].action.workBundleName||a.name)}</div><h4>Action breakdown</h4>${actionRows(a)}<p>Keep the load with one actor until a reviewed handoff or set-down.</p></div></details>`).join('')}<div class="compact-flow-end">End of process</div></div>`;
}

export function processLibraryView(ctx, embedded=false) {
  const areas=[...new Set(PROCESS_LIBRARY.map(p=>p.area))];
  const types=[...new Set(PROCESS_LIBRARY.flatMap(p=>p.warehouseTypes))].sort();
  const filtered=PROCESS_LIBRARY.filter(p=>(!ctx.processArea||p.area===ctx.processArea)&&(!ctx.warehouseType||p.warehouseTypes.includes(ctx.warehouseType)));
  const t=filtered.find(p=>p.id===ctx.libraryId)||filtered.find(p=>p.id==='klt-empty-tote-sorting-whiteboard')||filtered[0];
  const analysis=t?analyseProcess({actions:t.actions},ctx.w.configs):null;
  const activities=t?[...new Set(t.actions.map(a=>a.activityId||a.taskGroup))].map((id,i)=>{
    const rows=analysis.rows.filter(r=>(r.action.activityId||r.action.taskGroup)===id);
    const bundles=analysis.bundles.filter(b=>b.rows.some(r=>rows.includes(r)));
    const retained=rows.some(r=>r.action.humanRetained),gap=rows.some(r=>!r.action.humanRetained&&!r.candidates.length);
    const blocked=bundles.some(b=>!b.candidates.length);
    return {id,index:i+1,name:rows[0].action.taskGroup,rows,status:retained?'Human review':gap?'Capability gap':blocked?'Keep bundle together':'Conditional candidate',tone:blocked?'amber':'green'};
  }):[];
  const actionRows=a=>a.rows.map(r=>`<div class="step-action"><strong>${h(r.action.workElement)}</strong><div class="capability-tags">${r.action.requiredCapabilities.map(cap=>`<span>${h(cap)}</span>`).join('')}</div><span class="step-actor ${r.candidates.length?'candidate':'human'}">${r.candidates.length?'Conditional technology':'Human / existing equipment'}</span><small>${r.candidates.length?r.candidates.map(v=>h(v.name)).join(' · '):h(r.reason)}</small></div>`).join('');
  const areaCards=`<nav class="process-area-grid" aria-label="Process areas">${[['', 'All areas'],...areas.map(a=>[a,a])].map(([id,name],i)=>{
    const count=PROCESS_LIBRARY.filter(p=>!id||p.area===id).length;
    return `<button class="process-area-card ${ctx.processArea===id?'selected':''}" data-action="choose-process-area" data-id="${h(id)}" aria-pressed="${ctx.processArea===id}"><span class="area-icon">${icon(['layers','down','arrow','grid','person','robot'][i%6])}</span><span><strong>${h(name)}</strong><small>${count} ${count===1?'process':'processes'}</small></span><span class="area-count">${count}</span></button>`;
  }).join('')}</nav>`;
  const tree=`<aside class="process-tree" aria-label="Process explorer"><div class="explorer-title"><strong>Processes</strong><span>${filtered.length}</span></div><label class="field">Warehouse or storage type<select data-action="warehouse-type" aria-label="Warehouse or storage type"><option value="">All types</option>${safeOptions(types,ctx.warehouseType)}</select></label><label class="field">Select process<select data-action="library-process" aria-label="Library process">${safeOptions(filtered.map(p=>[p.id,p.name]),t?.id)}</select></label><div class="process-tree-groups">${areas.filter(a=>filtered.some(p=>p.area===a)).map(area=>`<details ${area===t?.area?'open':''}><summary>${h(area)} <span>${filtered.filter(p=>p.area===area).length}</span></summary><div>${filtered.filter(p=>p.area===area).map(p=>`<button data-action="choose-library-process" data-id="${h(p.id)}" class="${t?.id===p.id?'selected':''}" aria-pressed="${t?.id===p.id}"><span>${h(p.name)}</span><small>${p.actions.length} actions</small></button>`).join('')}</div></details>`).join('')}</div></aside>`;
  const flow=t?`<section class="process-canvas" aria-label="Selected process"><div class="process-canvas-heading"><div><span class="process-context">${h(t.area)} / ${h(t.warehouseTypes.join(' / '))}</span><h2>${h(t.name)}</h2><p>Engineering draft · ${activities.length} activities · ${t.actions.length} actions</p></div>${button('Create evaluation','start-process',{id:t.id,kind:'primary',iconName:'plus'})}</div>
    <div class="process-view-tabs" aria-label="Process views"><button class="selected" data-action="process-visual-tab" data-id="flow" aria-pressed="true">${icon('layers')}Activity flow</button></div>
    <div data-process-pane="flow"><div class="engineering-toolbar"><div class="flow-legend"><span><i class="green-key"></i>Conditional technology</span><span><i class="amber-key"></i>Human / gap / bundle constraint</span></div><button class="button quiet" data-action="expand-process-activities">Expand all steps</button></div><p class="engineering-hint">Process → steps → atomic actions. Select a step to expand capability and assignment details.</p>${compactProcessFlow(activities,actionRows)}<details class="process-branch"><summary>Exceptions and repeat rules</summary><p>${h(t.branches)}</p><p>This diagram shows the draft activity order. Confirm the selected path and return loops before use.</p></details></div><div class="process-footnote">Conditional matches are screening results. Task times, loads, repeat counts, site limits, and costs need confirmation. Action counts are not labour savings.</div></section>`:empty('No processes match','Change the process area or warehouse type.');
  return `${embedded?'':`<div class="page-heading"><div><h1>Process library</h1><p>Browse process areas. Select a process to inspect its flow and action breakdown.</p></div></div>`}<div class="visual-process-library">${areaCards}<div class="process-workspace">${tree}${flow}</div></div>`;
}

export function processAnalysisView(ctx) {
  const c=ctx.c,t=PROCESS_LIBRARY.find(x=>x.id===c.processTemplateId),a=analyseProcess(c,ctx.w.configs);
  const activities=[...new Set(c.actions.map(x=>x.activityId||x.taskGroup||x.id))].map(id=>{const rows=a.rows.filter(r=>(r.action.activityId||r.action.taskGroup||r.action.id)===id);const bundles=a.bundles.filter(b=>b.rows.some(r=>rows.includes(r)));return {name:rows[0].action.taskGroup,rows,bundleBlocked:bundles.some(b=>!b.candidates.length),candidates:ctx.w.configs.filter(v=>v.realProduct&&rows.every(r=>r.candidates.some(x=>x.id===v.id)))};});
  return `${panel('Activity and capability analysis','Generated from the selected process and the real product library. Conditional candidates are not validated automation.',`<div class="metrics small-metrics">${metric('Draft actions',number(a.rows.length,0),'No measured times')}${metric('Conditional candidates',number(a.conditional,0),'Action count only · not labour savings')}${metric('Human decisions retained',number(a.retained,0),'Draft operating policy')}${metric('Capability gaps',number(a.gaps,0),'Keep human or existing equipment')}</div><div class="callout subtle"><p>${h(t?.basis||'Review the edited source process.')} Review every exception path, handoff, recovery, and repeat count. Remove skipped branch actions from this case. Set repeat counts per output unit. Complete the numeric inputs before economics.</p></div><p><strong>Branches and repeat rules:</strong> ${h(t?.branches||'Confirm the selected path.')}</p><div class="activity-sequence">${activities.map((b,i)=>`<div><span>${i+1}</span><strong>${h(b.name)}</strong><small>${i?'After activity '+i:'Start'} → ${i===activities.length-1?'End':'next activity'}</small>${chip(b.bundleBlocked?'Bundle: retain / redesign':b.candidates.length?'Bundle: conditional':'Activity: retain / redesign',!b.bundleBlocked&&b.candidates.length?'green':'amber')}</div>`).join('')}</div><p class="muted">Draft assignment uses complete carried-load bundles, which can span more than one activity. Splitting a held load needs a reviewed handoff.</p>${table(['Work bundle','Conditional products','Assignment basis'],a.bundles.map(b=>row([h(b.name),b.candidates.length?b.candidates.map(v=>h(v.name)).join('<br>'):'Retain human / existing equipment, or redesign the handoff',b.candidates.length?'One product must support every action in this bundle. Confirm task performance before assignment.':b.rows.filter(r=>!r.candidates.length).map(r=>h(r.action.workElement)+': '+h(r.reason)).join('<br>')||'Individual actions have candidates, but no single product supports the complete bundle. A reviewed handoff or process change is required.'])))}${table(['Activity / action','Capabilities','Human / equipment role','Conditional real products','Before it / evidence needed'],a.rows.map(r=>row([`<strong>${h(r.action.taskGroup)}</strong><small>${h(r.action.workElement)}</small>`,h((r.action.requiredCapabilities||[]).join(', ')),`${chip(r.status,r.candidates.length?'green':'amber')}<small>${h(r.reason)}</small>`,r.candidates.length?r.candidates.map(v=>h(v.name)).join('<br>'):'No complete candidate in this library',`<small>${h(r.action.dependency?c.actions.find(x=>x.id===r.action.dependency)?.workElement||r.action.dependency:'Start')}</small><small>Load, reach, route, frequency, timing, tool, and reliability need confirmation.</small>`])))}<div class="toolbar"><span>${chip(c.templateReviewed?'Source path reviewed':'Owner review required',c.templateReviewed?'green':'amber')}</span>${button('Confirm source path and action draft','review-process',{kind:'secondary'})}${button('Rebuild work-split drafts','analyse-process',{kind:'secondary'})}${button('Go to business case','case-tab',{id:'Results',kind:'primary'})}</div>`)} `;
}
